import numpy as np
from pde import CartesianGrid, ScalarField
from pde.pdes.base import SDEBase
from pde.tools.typing import NumericArray

class RealizationPDE(SDEBase):
    use_noise_variance = False
    use_noise_realization = True
    def evolution_rate(self, state, t=0):
        return 0 * state
    def make_evolution_rate(self, state, backend):
        def ev(state_data: NumericArray, t: float):
            return np.zeros_like(state_data)
        return ev
    def make_noise_realization(self, state, backend):
        data_shape = state.data.shape
        def noise_realization(state_data, t):
            return np.ones(data_shape, dtype=state_data.dtype)
        return noise_realization

grid=CartesianGrid([[0,32]],8)
initial=ScalarField(grid,0.)
